// dist/engine.min.js - Consolidated Standalone Engine Bundle for CDN & CodePen
(function(global) {
  // --- LEXER ---
  function parseCode(sourceCode) {
    const lines = sourceCode
      .split('\n')
      .map(line => line.trim())
      .filter(line => line.length > 0 && !line.startsWith('#'));

    const program = { config: null, body: [], events: {} };
    let currentEventTarget = null;

    for (const line of lines) {
      if (line === 'End') {
        currentEventTarget = null;
        continue;
      }
      if (line.startsWith('On click')) {
        const eventMatch = line.match(/^On click\s+(\w+):$/i);
        if (eventMatch) {
          currentEventTarget = eventMatch[1];
          program.events[currentEventTarget] = { statements: [] };
        }
        continue;
      }
      const statement = parseStatement(line, program);
      if (statement) {
        if (currentEventTarget) {
          program.events[currentEventTarget].statements.push(statement);
        } else {
          program.body.push(statement);
        }
      }
    }
    return program;
  }

  function parseStatement(line, program) {
    let match = line.match(/^Create window titled "([^"]+)" size (\d+)\s*x\s*(\d+)$/i);
    if (match) {
      program.config = { title: match[1], width: parseInt(match[2], 10), height: parseInt(match[3], 10) };
      return null;
    }
    match = line.match(/^Set (\w+) to (.+)$/i);
    if (match && !line.startsWith('Set text of')) {
      return { type: 'SET_VAR', name: match[1], value: match[2].trim() };
    }
    match = line.match(/^Increase (\w+) by (\d+)$/i);
    if (match) {
      return { type: 'INCREMENT_VAR', name: match[1], by: parseInt(match[2], 10) };
    }
    match = line.match(/^Set text of (\w+) to (.+)$/i);
    if (match) {
      return { type: 'UPDATE_ELEMENT', elementId: match[1], value: match[2].trim() };
    }
    match = line.match(/^Draw box at (\d+),\s*(\d+) size (\d+)\s*x\s*(\d+) filled with "([^"]+)" as (\w+)$/i);
    if (match) {
      return {
        type: 'CREATE_BOX',
        payload: { id: match[6], type: 'box', x: parseInt(match[1], 10), y: parseInt(match[2], 10), w: parseInt(match[3], 10), h: parseInt(match[4], 10), color: match[5] }
      };
    }
    match = line.match(/^Draw text "([^"]+)" at (\d+),\s*(\d+) colored "([^"]+)" as (\w+)$/i);
    if (match) {
      return {
        type: 'CREATE_TEXT',
        payload: { id: match[5], type: 'text', text: match[1], x: parseInt(match[2], 10), y: parseInt(match[3], 10), color: match[4] }
      };
    }
    match = line.match(/^Draw button "([^"]+)" at (\d+),\s*(\d+) size (\d+)\s*x\s*(\d+) colored "([^"]+)" as (\w+)$/i);
    if (match) {
      return {
        type: 'CREATE_BUTTON',
        payload: { id: match[7], type: 'button', text: match[1], x: parseInt(match[2], 10), y: parseInt(match[3], 10), w: parseInt(match[4], 10), h: parseInt(match[5], 10), color: match[6] }
      };
    }
    return null;
  }

  // --- MEMORY STORE / VM ---
  class MemoryStore {
    constructor() { this.variables = {}; this.uiElements = []; }
    clear() { this.variables = {}; this.uiElements = []; }
    set(name, value) { this.variables[name] = value; }
    increment(name, byAmount = 1) {
      const currentVal = Number(this.variables[name]) || 0;
      this.variables[name] = currentVal + byAmount;
    }
    updateText(elementId, textValue) {
      const element = this.uiElements.find(item => item.id === elementId);
      if (element) element.text = String(textValue);
    }
    addUIElement(payload) {
      const idx = this.uiElements.findIndex(item => item.id === payload.id);
      if (idx !== -1) this.uiElements[idx] = { ...payload };
      else this.uiElements.push({ ...payload });
    }
    getRenderList() { return this.uiElements; }
    evaluate(expression) {
      if (typeof expression !== 'string') return expression;
      const trimmed = expression.trim();
      if (trimmed.includes('+')) {
        return trimmed.split('+').map(part => this.evaluate(part.trim())).join('');
      }
      if (trimmed.startsWith('"') && trimmed.endsWith('"')) return trimmed.slice(1, -1);
      if (!isNaN(trimmed) && trimmed !== '') return Number(trimmed);
      if (Object.prototype.hasOwnProperty.call(this.variables, trimmed)) return this.variables[trimmed];
      return trimmed;
    }
  }

  // --- RENDERER ---
  class CanvasRenderer {
    constructor(canvas) {
      this.canvas = canvas;
      this.ctx = canvas.getContext('2d');
    }
    resize(width, height) { this.canvas.width = width; this.canvas.height = height; }
    clear() { this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height); }
    render(uiElements) {
      this.clear();
      for (const element of uiElements) {
        if (element.type === 'box') {
          this.ctx.fillStyle = element.color || '#333333';
          this.ctx.fillRect(element.x, element.y, element.w, element.h);
        } else if (element.type === 'text') {
          this.ctx.fillStyle = element.color || '#ffffff';
          this.ctx.font = '16px monospace';
          this.ctx.textAlign = 'left';
          this.ctx.textBaseline = 'alphabetic';
          this.ctx.fillText(element.text, element.x, element.y);
        } else if (element.type === 'button') {
          this.ctx.fillStyle = element.color || '#007acc';
          this.ctx.fillRect(element.x, element.y, element.w, element.h);
          this.ctx.fillStyle = '#ffffff';
          this.ctx.font = 'bold 14px sans-serif';
          this.ctx.textAlign = 'center';
          this.ctx.textBaseline = 'middle';
          this.ctx.fillText(element.text, element.x + element.w / 2, element.y + element.h / 2);
          this.ctx.textAlign = 'left';
          this.ctx.textBaseline = 'alphabetic';
        }
      }
    }
  }

  // --- EVENT MANAGER ---
  class EventManager {
    constructor(canvas, onTrigger) {
      this.canvas = canvas;
      this.onTrigger = onTrigger;
      this.clickables = [];
      this.canvas.addEventListener('click', (e) => this.handleClick(e));
    }
    clear() { this.clickables = []; }
    registerClickable(element) {
      const idx = this.clickables.findIndex(item => item.id === element.id);
      if (idx !== -1) this.clickables[idx] = element;
      else this.clickables.push(element);
    }
    handleClick(event) {
      const rect = this.canvas.getBoundingClientRect();
      const scaleX = this.canvas.width / rect.width;
      const scaleY = this.canvas.height / rect.height;
      const clickX = (event.clientX - rect.left) * scaleX;
      const clickY = (event.clientY - rect.top) * scaleY;

      for (const element of this.clickables) {
        if (
          clickX >= element.x &&
          clickX <= element.x + element.w &&
          clickY >= element.y &&
          clickY <= element.y + element.h
        ) {
          this.onTrigger(element.id);
        }
      }
    }
  }

  // --- MAIN VM FACADE ---
  class EnglishVM {
    constructor(canvasId) {
      this.canvas = document.getElementById(canvasId);
      if (!this.canvas) {
        throw new Error(`Canvas element with ID "${canvasId}" was not found.`);
      }
      this.renderer = new CanvasRenderer(this.canvas);
      this.memory = new MemoryStore();
      this.events = new EventManager(this.canvas, (id) => this.handleEventTrigger(id));
      this.program = null;
    }
    reset() {
      this.memory.clear();
      this.events.clear();
      this.renderer.clear();
    }
    parseAndRun(sourceCode) {
      this.reset();
      this.program = parseCode(sourceCode);
      if (this.program.config) {
        this.renderer.resize(this.program.config.width, this.program.config.height);
      }
      this.executeStatements(this.program.body);
      this.renderer.render(this.memory.getRenderList());
    }
    executeStatements(statements) {
      for (const stmt of statements) this.executeStatement(stmt);
    }
    executeStatement(stmt) {
      switch (stmt.type) {
        case 'SET_VAR':
          this.memory.set(stmt.name, this.memory.evaluate(stmt.value));
          break;
        case 'INCREMENT_VAR':
          this.memory.increment(stmt.name, stmt.by);
          break;
        case 'UPDATE_ELEMENT':
          this.memory.updateText(stmt.elementId, this.memory.evaluate(stmt.value));
          break;
        case 'CREATE_BOX':
        case 'CREATE_TEXT':
          this.memory.addUIElement(stmt.payload);
          break;
        case 'CREATE_BUTTON':
          this.memory.addUIElement(stmt.payload);
          this.events.registerClickable(stmt.payload);
          break;
      }
    }
    handleEventTrigger(targetId) {
      const eventHandler = this.program.events[targetId];
      if (eventHandler) {
        this.executeStatements(eventHandler.statements);
        this.renderer.render(this.memory.getRenderList());
      }
    }
  }

  // Export to global scope for CDN / CodePen usage
  global.EnglishVM = EnglishVM;
})(typeof window !== 'undefined' ? window : this);
